// GENERATED by `npm run sync-core` from extension/src/core — do not edit here.
// Text helpers shared by the extension and the backend.
// Note: code-point escapes use the \u{...} form (regexes with the `u` flag) on purpose.

// Control characters, zero-width / bidi overrides, line separators and BOM: removed from any text
// sent to the model.
const UNSAFE_CHARS = /[\u{0}-\u{1F}\u{7F}-\u{9F}\u{200B}-\u{200F}\u{2028}-\u{202E}\u{2060}-\u{2064}\u{2066}-\u{2069}\u{FEFF}]/gu;

// One emoji "cluster" at the start of a string: flag (2 regional indicators), or pictograph with
// optional variation selector / keycap / skin tone, possibly joined by ZWJ (e.g. "office worker").
const EMOJI_CLUSTER =
  /^(?:\p{Regional_Indicator}{2}|\p{Extended_Pictographic}(?:\u{FE0F}|\u{20E3}|[\u{1F3FB}-\u{1F3FF}])*(?:\u{200D}\p{Extended_Pictographic}(?:\u{FE0F}|[\u{1F3FB}-\u{1F3FF}])*)*)/u;

// Any emoji-related code point (used to strip emojis from group names).
const EMOJI_ANYWHERE = /[\p{Extended_Pictographic}\p{Regional_Indicator}\u{200D}\u{FE0F}\u{20E3}\u{1F3FB}-\u{1F3FF}]/gu;

const COMBINING_MARKS = /[\u{300}-\u{36F}]/gu;
const ELLIPSIS = '\u{2026}';

/** Truncate without cutting a surrogate pair; appends an ellipsis when shortened. */
export function truncate(text, maxLength) {
  if (!maxLength || text.length <= maxLength) return text;
  let cut = text.slice(0, Math.max(0, maxLength - 1));
  const last = cut.charCodeAt(cut.length - 1);
  if (last >= 0xd800 && last <= 0xdbff) cut = cut.slice(0, -1);
  return `${cut.trimEnd()}${ELLIPSIS}`;
}

/** Remove unsafe characters, collapse whitespace, trim and truncate. Non-strings become ''. */
export function cleanText(value, maxLength) {
  if (typeof value !== 'string') return '';
  const text = value.replace(UNSAFE_CHARS, ' ').replace(/\s+/g, ' ').trim();
  return truncate(text, maxLength);
}

/** Lowercase + strip diacritics ("Côté Écoles" -> "cote ecoles"). */
export function foldText(text) {
  return String(text ?? '')
    .normalize('NFD')
    .replace(COMBINING_MARKS, '')
    .toLowerCase();
}

export function stripEmojis(text) {
  return String(text ?? '').replace(EMOJI_ANYWHERE, ' ').replace(/\s+/g, ' ').trim();
}

/** Stable comparison key for group names: folded, punctuation-insensitive, emoji-free. */
export function nameKey(name) {
  return foldText(stripEmojis(name))
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim();
}

/** Return the first emoji cluster of `value`, or '' if it does not start with an emoji. */
export function sanitizeEmoji(value) {
  if (typeof value !== 'string') return '';
  const match = value.trim().match(EMOJI_CLUSTER);
  return match && match[0].length <= 16 ? match[0] : '';
}

/** "<emoji> Voitures" -> { emoji: "<emoji>", name: "Voitures" }. */
export function splitLeadingEmoji(title) {
  const text = String(title ?? '').trim();
  const match = text.match(EMOJI_CLUSTER);
  if (!match) return { emoji: '', name: text };
  return { emoji: match[0], name: text.slice(match[0].length).trim() };
}

/** Capitalise the first letter (locale-aware) without touching the rest. */
export function capitalize(text) {
  if (!text) return text;
  const [first, ...rest] = Array.from(text);
  return first.toLocaleUpperCase() + rest.join('');
}

/** Tokenise folded text into words (letters/digits, any script). */
export function tokenize(text) {
  return foldText(text).split(/[^\p{L}\p{N}]+/u).filter(Boolean);
}
